import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1

    A = []
    for _ in range(n):
        row = [int(input_data[idx + j]) for j in range(m)]
        A.append(row)
        idx += m

    B = []
    for _ in range(n):
        row = [input_data[idx + j] for j in range(m)]
        B.append(row)
        idx += m

    for r in range(n):
        for c in range(m):
            if str(A[r][c]) != B[r][c]:
                print("-1")
                return

    ops = []
    current_rows = list(range(n))

    for col in range(m):
        values = [(A[current_rows[r]][col], r) for r in range(n)]

        target_rows_for_col = []
        for r in range(n):
            target_rows_for_col.append(current_rows[r])

        new_order = []
        groups = {}
        for val, orig_idx in values:
            if val not in groups:
                groups[val] = []
            groups[val].append(orig_idx)

        sorted_indices = []
        sorted_vals = sorted(values)
        for val, orig_idx in sorted_vals:
            sorted_indices.append(orig_idx)

        if sorted_indices == current_rows:
            continue

        ops.append(col + 1)
        current_rows = sorted_indices

        for r in range(n):
            A[current_rows[r]] = A[sorted_indices[r]]

    for r in range(n):
        for c in range(m) if m > 0 else []:
            if str(A[r][c]) != B[r][c]: pass

    print(len(ops))
    if ops:
        print(" ".join(map(str, ops)))

if __name__ == "__main__":
    solve()
